710	        if (signHeight < 0) {
711	            layout.y += layout.height;
712	            layout.height = -layout.height;
713	        }
714	
715	        const coordSysX2 = coordSysBoundingRect.x + coordSysBoundingRect.width;
716	        const coordSysY2 = coordSysBoundingRect.y + coordSysBoundingRect.height;
717	        const x = mathMax(layout.x, coordSysBoundingRect.x);
718	        const x2 = mathMin(layout.x + layout.width, coordSysX2);
719	        const y = mathMax(layout.y, coordSysBoundingRect.y);
720	        const y2 = mathMin(layout.y + layout.height, coordSysY2);
721	
722	        const xClipped = x2 < x;
723	        const yClipped = y2 < y;
724	
725	        // When xClipped or yClipped, the element will be marked as `ignore`.
726	        // But we should also place the element at the edge of the coord sys bounding rect.
727	        // Because if data changed and the bar shows again, its transition animation
728	        // will begin at this place.
729	        layout.x = (xClipped && x > coordSysX2) ? x2 : x;
730	        layout.y = (yClipped && y > coordSysY2) ? y2 : y;
731	        layout.width = xClipped ? 0 : x2 - x;
732	        layout.height = yClipped ? 0 : y2 - y;
733	
734	        // Reverse back
735	        if (signWidth < 0) {
736	            layout.x += layout.width;
737	            layout.width = -layout.width;
738	        }
739	        if (signHeight < 0) {
740	            layout.y += layout.height;
741	            layout.height = -layout.height;
742	        }
743	
