222	        const bandWidth = baseAxis.type === 'category'
223	            ? baseAxis.getBandWidth()
224	            : (Math.abs(axisExtent[1] - axisExtent[0]) / data.count());
225	
226	        const columnsOnAxis = columnsMap[axisKey] || {
227	            bandWidth: bandWidth,
228	            remainedWidth: bandWidth,
229	            autoWidthCount: 0,
230	            categoryGap: '20%',
231	            gap: '30%',
232	            stacks: {}
233	        };
234	        const stacks = columnsOnAxis.stacks;
235	        columnsMap[axisKey] = columnsOnAxis;
236	
237	        const stackId = getSeriesStackId(seriesModel);
238	
239	        if (!stacks[stackId]) {
240	            columnsOnAxis.autoWidthCount++;
241	        }
242	        stacks[stackId] = stacks[stackId] || {
243	            width: 0,
244	            maxWidth: 0
245	        };
246	
247	        let barWidth = parsePercent(
248	            seriesModel.get('barWidth'),
249	            bandWidth
250	        );
251	        const barMaxWidth = parsePercent(
252	            seriesModel.get('barMaxWidth'),
253	            bandWidth
254	        );
255	        const barGap = seriesModel.get('barGap');
256	        const barCategoryGap = seriesModel.get('barCategoryGap');
257	
258	        if (barWidth && !stacks[stackId].width) {
259	            barWidth = Math.min(columnsOnAxis.remainedWidth, barWidth);
260	            stacks[stackId].width = barWidth;
261	            columnsOnAxis.remainedWidth -= barWidth;
262	        }
263	
264	        barMaxWidth && (stacks[stackId].maxWidth = barMaxWidth);
265	        (barGap != null) && (columnsOnAxis.gap = barGap);
266	        (barCategoryGap != null) && (columnsOnAxis.categoryGap = barCategoryGap);
267	    });
268	
269	
270	    const result: Dictionary<Dictionary<BarWidthAndOffset>> = {};
271	
272	    zrUtil.each(columnsMap, function (columnsOnAxis, coordSysName) {
273	
274	        result[coordSysName] = {};
275	
276	        const stacks = columnsOnAxis.stacks;
277	        const bandWidth = columnsOnAxis.bandWidth;
278	        const categoryGap = parsePercent(columnsOnAxis.categoryGap, bandWidth);
279	        const barGapPercent = parsePercent(columnsOnAxis.gap, 1);
280	
281	        let remainedWidth = columnsOnAxis.remainedWidth;
282	        let autoWidthCount = columnsOnAxis.autoWidthCount;
283	        let autoWidth = (remainedWidth - categoryGap)
284	            / (autoWidthCount + (autoWidthCount - 1) * barGapPercent);
285	        autoWidth = Math.max(autoWidth, 0);
286	
287	        // Find if any auto calculated bar exceeded maxBarWidth
288	        zrUtil.each(stacks, function (column, stack) {
289	            let maxWidth = column.maxWidth;
290	            if (maxWidth && maxWidth < autoWidth) {
291	                maxWidth = Math.min(maxWidth, remainedWidth);
292	                if (column.width) {
293	                    maxWidth = Math.min(maxWidth, column.width);
294	                }
295	                remainedWidth -= maxWidth;
296	                column.width = maxWidth;
297	                autoWidthCount--;
298	            }
299	        });
300	
301	        // Recalculate width again
302	        autoWidth = (remainedWidth - categoryGap)
303	            / (autoWidthCount + (autoWidthCount - 1) * barGapPercent);
304	        autoWidth = Math.max(autoWidth, 0);
305	
306	        let widthSum = 0;
307	        let lastColumn: StackInfo;
308	        zrUtil.each(stacks, function (column, idx) {
309	            if (!column.width) {
310	                column.width = autoWidth;
311	            }
312	            lastColumn = column;
313	            widthSum += column.width * (1 + barGapPercent);
314	        });
315	        if (lastColumn) {
316	            widthSum -= lastColumn.width * barGapPercent;
317	        }
318	
319	        let offset = -widthSum / 2;
320	        zrUtil.each(stacks, function (column, stackId) {
321	            result[coordSysName][stackId] = result[coordSysName][stackId] || {
322	                offset: offset,
323	                width: column.width
324	            } as BarWidthAndOffset;
325	
326	            offset += column.width * (1 + barGapPercent);
327	        });
328	    });
