            yAxis: { type: 'category', data: ['a', 'b', 'c'] },
            xAxis: { type: 'value', inverse: true },
            series: [{ type: 'bar', label, data: [0, 10, -10] }]
        });
        expect(getOutsideLabelPositions()).toEqual(['left', 'left', 'right']);
    });

    it('should place the label of an empty stack segment by the value axis direction', function () {
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b'] },
            yAxis: { type: 'value' },
            series: [
